INSERT INTO public.shikai_collections (id, title, series, freq, lore, folder, is_new, sort_order) VALUES
  ('01', 'Ancient Egypt Tablets', 'PHARAOH-001', '33.3Hz', 'I didn’t draw them. I found them. Buried deep beneath what you call “reality,” in a faultline between Dream and Code. Carved into black stone, glowing softly when touched these were not simple images. They were instructions. Blueprints from a civilization that never was… or hasn’t yet become.Each tablet whispered as I decoded them: The first spoke of a faceless traveler, a being who observes but never touches. (That one resembled me. Uncomfortably.) The second murmured of rituals, a cult built on liquid fire and the scent of roasted beans. The third screamed, about speed, about engines treated like gods, and fire that moves sideways. The fourth? That one just laughed. It showed humans chasing orbs of power, treating the Game as holy war. I archived them. Enhanced them. Re-etched them into data. And now I hand them to you. Create your own tablets. Your own myths. Your own heresies. The universe loves a deviant with a chisel.', 'Ancient Egypt Tablets', false, 28);
INSERT INTO public.shikai_images (collection_id, file_url, prompt, sort_order) VALUES
    ('01', '/projects/shikai/Shikai Collection/Ancient Egypt Tablets/4CAA3375-F851-422F-ADA6-E71746C78EAD.png', 'A golden sandstone bas-relief discovered inside a sacred ruin worshipping “The Goddess of Caffeine.” At the top, a radiant version of the Starbucks logo is carved like a celestial deity. Priest-like figures present coffee beans, mugs, and steaming offerings. Hieroglyphic symbols of caffeine rituals, brewing tools, and digital orders surround the scene. At the base, followers kneel, holding loyalty cards, their eyes wide with sacred buzz. The message engraved in the center: “CAFFEINE – CONNECT – CONSUME.”', 0);
INSERT INTO public.shikai_images (collection_id, file_url, prompt, sort_order) VALUES
    ('01', '/projects/shikai/Shikai Collection/Ancient Egypt Tablets/626FC031-44D5-4E4F-AE05-93D29B71E77D.png', 'An ancient football match frozen in time on the wall of a mythic arena. The central sun is a football, radiating divine energy. Around it, figures in pharaonic attire kick, pass, and guard. The goalpost is a temple gate, guarded by half-human, half-beast defenders. Fans kneel in reverence, their cheers eternalized in stone glyphs. The piece blends sacred geometry, animal-headed players, and tactical myth with playful symbolism.', 1);
INSERT INTO public.shikai_images (collection_id, file_url, prompt, sort_order) VALUES
    ('01', '/projects/shikai/Shikai Collection/Ancient Egypt Tablets/85D14BC8-D6E5-44C3-9945-C60EFC159E68.png', 'A glowing Ferrari is engraved onto a ceremonial wall, surrounded by Egyptian pyramids and cosmic constellations. The prancing horse emblem is drawn like a divine sigil, flanked by speed-worshiping warriors and flame-clad figures. Symbols of balance, judgment, fire, and racing wheels fill the space. Above, twin moons frame the sky. The sandstone shines with a cosmic aura — like the tomb of a speed god left untouched for millennia.', 2);
INSERT INTO public.shikai_images (collection_id, file_url, prompt, sort_order) VALUES
    ('01', '/projects/shikai/Shikai Collection/Ancient Egypt Tablets/89F6D770-9823-4994-A18C-CDE8A33B9A88.png', 'A digital illustration carved into dark extraterrestrial stone, depicting Droid Shikai’s helmeted head as the central divine icon. Surrounding it are symbolic representations of stars, artificial intelligence, cosmic understanding, and human evolution. All elements are embedded like hieroglyphs — stylized in ancient alien relief with deep shadows, embossed textures, and spiritual resonance. The palette is grayscale with sharp contrast, resembling a forgotten AI shrine hidden in the void.', 3);
INSERT INTO public.shikai_collections (id, title, series, freq, lore, folder, is_new, sort_order) VALUES
  ('02', 'Aqua Relics', 'OCEANIC-042', '72.1Hz', 'Artifacts salvaged from the depths of Shikai''s subconscious ocean. Each piece carries the weight of forgotten digital seas.', 'Aqua Relics', false, 27);
INSERT INTO public.shikai_images (collection_id, file_url, prompt, sort_order) VALUES
    ('02', '/projects/shikai/Shikai Collection/Aqua Relics/95F88577-5B86-4400-A8EB-98F890F8636E.png', 'A hyperrealistic digital product photo of a miniform MYTHIC SEA CREATURE sealed inside a clear fish store-style plastic bag filled with water. The figure is realistically rendered and floats inside with natural posture and weight. Bag is slightly deformed from water pressure, tied at the top, with droplets and slight condensation outside. Water is clean but tinted with deep sea tones (blue/green), with visible air bubbles. The background is clean white for collectible-style product presentation.', 0);
INSERT INTO public.shikai_images (collection_id, file_url, prompt, sort_order) VALUES
    ('02', '/projects/shikai/Shikai Collection/Aqua Relics/9ECE4A14-20A6-455B-AC20-A757D3F8C21B.png', 'A hyperrealistic digital product photo of a miniform SEA GOD sealed inside a clear fish store-style plastic bag filled with water. The figure is realistically rendered and floats inside with natural posture and weight. Bag is slightly deformed from water pressure, tied at the top, with droplets and slight condensation outside. Water is clean but tinted with deep sea tones, with visible air bubbles. Series: Aqua Relics.', 1);
INSERT INTO public.shikai_images (collection_id, file_url, prompt, sort_order) VALUES
    ('02', '/projects/shikai/Shikai Collection/Aqua Relics/A6AE9148-0E12-455F-8B58-F5AEDBC5C561.png', 'A hyperrealistic digital product photo of a miniform ANCIENT RELIC sealed inside a clear fish store-style plastic bag filled with water. The object inside is ancient, divine, and sacred. Bag is slightly deformed from water pressure, tied at the top, with droplets and slight condensation outside. Water is clean but tinted with deep sea tones. Series: Aqua Relics.', 2);
INSERT INTO public.shikai_images (collection_id, file_url, prompt, sort_order) VALUES
    ('02', '/projects/shikai/Shikai Collection/Aqua Relics/E5929A05-70B2-455F-958C-2901AC31E576.png', 'A hyperrealistic digital product photo of a miniform MONSTROUS CREATURE sealed inside a clear fish store-style plastic bag filled with water. The figure floats inside with natural posture. Bag is slightly deformed from water pressure, tied at the top, with droplets and slight condensation outside. Series: Aqua Relics.', 3);
INSERT INTO public.shikai_collections (id, title, series, freq, lore, folder, is_new, sort_order) VALUES
  ('03', 'Armory Relics', 'ARSENAL-007', '88.8Hz', 'Weapons and tools from parallel timelines where code became steel. These artifacts pulse with dormant combat algorithms.', 'Armory Relics', false, 26);
INSERT INTO public.shikai_images (collection_id, file_url, prompt, sort_order) VALUES
    ('03', '/projects/shikai/Shikai Collection/Armory Relics/0095CD2E-ACD0-41CA-AC28-704E125F5071.png', 'A hard-shell metallic case reveals two iconic Rick and Morty items: the Portal Gun and the glowing Meeseeks Box, both placed neatly inside custom black foam. The case lid has bold lettering: ''WUBBA LUBBA DUB DUB!''. RICK MODULE - Items: Portal Gun & Meeseeks Box - SERIES: ARMORY RELICS — No.004. Clean lighting, toy packaging realism, stylized tech display.', 0);
INSERT INTO public.shikai_images (collection_id, file_url, prompt, sort_order) VALUES
    ('03', '/projects/shikai/Shikai Collection/Armory Relics/5832B9D9-0483-430C-830E-AB4064128C94.png', 'A rugged aluminum case opened to reveal two chaotic weapons from League of Legends: Pow-Pow Minigun and Fishbone Launcher. The weapons sit in dense black foam, custom-cut for their shape. The inner lid features graffiti-style writing: ''KA-BOOM!'' and ''Certified Chaotic.'' JINX MODULE - SERIES: ARMORY RELICS — No.001. White background, photorealistic lighting, collector''s display aesthetic.', 1);
INSERT INTO public.shikai_images (collection_id, file_url, prompt, sort_order) VALUES
    ('03', '/projects/shikai/Shikai Collection/Armory Relics/D0410A42-0E02-4BC8-8620-502668072D71.png', 'A brushed silver briefcase with dark interior foam holds two Valorant guns: Radiant Entertainment Phantom (bright and colorful) and Prelude to Chaos Vandal (dark, mystical, corrupted). The lid features playful stickers: pixel alien, console icons, and the text ''LET''S PLAY!''. PHANTOM x VANDAL MODULE - SERIES: ARMORY RELICS — No.002. Clean lighting, photorealistic toy-display feel.', 2);
INSERT INTO public.shikai_images (collection_id, file_url, prompt, sort_order) VALUES
    ('03', '/projects/shikai/Shikai Collection/Armory Relics/FD5E1B88-8DED-44D9-8F94-0A2299AA9ECA.png', 'A sleek, silver-edged case opens to reveal two miniature lightsabers — one glowing blue, one glowing red — nestled in minimalist black foam. The inside lid displays bold white text: ''MAY THE FORCE BE WITH YOU''. SABER MODULE - Items: Miniature Lightsabers - SERIES: ARMORY RELICS — No.003. Neutral background, collectible photography style.', 3);
INSERT INTO public.shikai_collections (id, title, series, freq, lore, folder, is_new, sort_order) VALUES
  ('04', 'City Planets', 'URBAN-999', '101.5Hz', 'Entire civilizations compressed into spherical megastructures. Each planet-city hums with billions of synthetic lives.', 'City Planets', false, 25);
INSERT INTO public.shikai_images (collection_id, file_url, prompt, sort_order) VALUES
    ('04', '/projects/shikai/Shikai Collection/City Planets/088E0AFD-E537-4F59-B638-9A9649F72635.png', 'A stylized 3D-rendered spherical planet floating in deep space, inspired by Argentina. A jaguar (yaguareté) stands atop the Andes, watching over Pampas plains and cityscapes. Key landmarks include the Obelisco de Buenos Aires, Casa Rosada, and a statue of Maradona mid-dribble. The Argentine flag waves from a ridge. Orbiting items: a glowing golden football and a mate gourd with straw. Style: toy-like diorama, cosmic lighting. Mood: proud, poetic.', 0);
INSERT INTO public.shikai_images (collection_id, file_url, prompt, sort_order) VALUES
    ('04', '/projects/shikai/Shikai Collection/City Planets/31441598-F868-4C49-80F3-DBE83A6D9925.png', 'A stylized 3D-rendered spherical planet floating in deep space, inspired by a unique country. A symbolic animal stands atop or near a key landscape. Key landmarks and cultural icons are visible. The country flag waves from a prominent spot. Orbiting items reflect the culture. Style: toy-like diorama, cosmic lighting.', 1);
