INSERT INTO public.shikai_collections (id, title, series, freq, lore, folder, is_new, sort_order) VALUES
  ('16', 'Traditional Carpets', 'WEAVE-1024', '24.0Hz', 'Textiles woven from digital threads. Each pattern tells stories of data streams becoming art across centuries.', 'Traditional Carpets', false, 13);
INSERT INTO public.shikai_images (collection_id, file_url, prompt, sort_order) VALUES
    ('16', '/projects/shikai/Shikai Collection/Traditional Carpets/19861F5A-FE19-4DB9-8B1B-FE4799378550.png', 'A traditional woven textile wall tapestry, vertically oriented (9:16), hanging from a dark wooden rod against a plain white wall. The central motif is a robotic bald eagle, detailed with bronze and steel-like armor plating, wings spread in a proud stance. The color palette leans into warm earthy tones and faded reds and blues. Around the eagle are symbols like a Route 66 sign, a silhouette of the Statue of Liberty, and Native American-inspired patterns. The fabric is ultra-realistic, with fibrous wool detail.', 0);
INSERT INTO public.shikai_images (collection_id, file_url, prompt, sort_order) VALUES
    ('16', '/projects/shikai/Shikai Collection/Traditional Carpets/6F3489B1-C0CF-4DA5-99D3-4A7F2A71F554.png', 'A traditional woven textile wall tapestry, vertically oriented (9:16), hanging from a dark wooden rod against a plain white wall. The central motif is a robotic koi fish, rendered with sleek metallic blue and gold scales and glowing red eyes, leaping upward amidst swirling stylized waves. The color palette reflects traditional Japanese design—deep red, cream, and gold. Cherry blossom branches frame the koi, with additional motifs including Mount Fuji, a Torii gate, and kanji symbols.', 1);
INSERT INTO public.shikai_images (collection_id, file_url, prompt, sort_order) VALUES
    ('16', '/projects/shikai/Shikai Collection/Traditional Carpets/7BD3B820-BAF5-421C-93E1-7F7897347A80.png', 'A traditional woven textile wall tapestry, vertically oriented (9:16), hanging from a dark wooden rod against a plain white wall. The central motif is a highly detailed, robotic Chinese dragon, featuring golden and jade-colored metallic scales and glowing red eyes. The tapestry uses a red, gold, and green color palette rooted in Chinese imperial tradition. Surrounding the dragon are woven cloud motifs, a lotus flower, a red paper lantern, and Chinese characters.', 2);
INSERT INTO public.shikai_images (collection_id, file_url, prompt, sort_order) VALUES
    ('16', '/projects/shikai/Shikai Collection/Traditional Carpets/E73B8EC1-489B-4019-A618-47A7BE7A87A1.png', 'A traditional woven textile wall tapestry, vertically oriented (9:16), hanging from a dark wooden rod against a plain white wall. The central motif is a highly detailed, robotic Van cat, infused with mechanical and metallic elements like synthetic fur plates and glowing heterochromatic eyes (one blue, one amber). The tapestry''s color palette features deep reds, navy blues, and golden tones, reflecting traditional Turkish motifs including Ottoman tulips, Seljuk stars, and Ay-Yıldız crescents.', 3);
INSERT INTO public.shikai_collections (id, title, series, freq, lore, folder, is_new, sort_order) VALUES
