INSERT INTO public.shikai_collections (id, title, series, freq, lore, folder, is_new, sort_order) VALUES
  ('27', 'Shikai Timeless Relics', 'TIME-RELIC', '∞Hz', 'Statues that exist outside of time. Each figure represents a moment of philosophical stillness, captured in eternal observation. These are not characters — they are ideas, frozen in form.', 'Shikai Timeless Relics', true, 2);
INSERT INTO public.shikai_images (collection_id, file_url, prompt, sort_order) VALUES
    ('27', '/projects/shikai/Shikai Collection/Shikai Timeless Relics/0E9F85A3-5510-4180-A3B5-CD7D30B3B7AC.PNG', 'A premium, high-end 3D-rendered collectible figurine from the SHIKAI TIME RELICS series. Museum-quality collectible statue with clean, minimal, philosophical tone. Photorealistic 3D render on pure white background with studio lighting and soft shadows. Single central human or humanoid form in calm, timeless posture. Matte stone/ceramic/porcelain finish with subtle surface imperfections. Vertical 9:16, centered framing, full figure visible. Timeless, quiet, philosophical mood.', 0);
