INSERT INTO public.shikai_collections (id, title, series, freq, lore, folder, is_new, sort_order) VALUES
  ('28', 'Shikai Cosmic Rides', 'COSMIC-RIDE', '88.8Hz', 'Vehicles from dimensions where machines dream of the stars. Each ride carries the soul of its pilot across infinite highways of light and shadow.', 'Shikai Cosmic Rides', true, 1);
INSERT INTO public.shikai_images (collection_id, file_url, prompt, sort_order) VALUES
    ('28', '/projects/shikai/Shikai Collection/Shikai Cosmic Rides/ChatGPT Image 24 Ara 2025 10_10_54.png', 'A premium 3D collectible vehicle designed for the Shikai Cosmic Rides series. Ultra-detailed 3D render on clean white studio background. Centered composition with soft realistic shadow. Museum-grade collectible product photography style. Hot Wheels-inspired proportions with slightly exaggerated toy-like forms. Mixed metals with scratches, dents, and wear. Visible bolts, plates, cables. Clear distinction between clean tech and junk tech. Vertical 9:16 aspect ratio. The vehicle is stationary, displayed as an artifact.', 0);
INSERT INTO public.shikai_images (collection_id, file_url, prompt, sort_order) VALUES
    ('28', '/projects/shikai/Shikai Collection/Shikai Cosmic Rides/ChatGPT Image 24 Ara 2025 10_18_45.png', 'A premium 3D collectible vehicle for the Shikai Cosmic Rides series. Ultra-detailed 3D render on white studio background. Centered, soft realistic shadow. Museum-grade collectible style. Hot Wheels-inspired proportions, exaggerated toy-like forms. Mixed metals with wear and improvised engineering. Visible mechanical parts. Vertical 9:16 aspect ratio.', 1);
INSERT INTO public.shikai_images (collection_id, file_url, prompt, sort_order) VALUES
    ('28', '/projects/shikai/Shikai Collection/Shikai Cosmic Rides/ChatGPT Image 24 Ara 2025 10_32_01.png', 'A premium 3D collectible vehicle for the Shikai Cosmic Rides series. Ultra-detailed 3D render on white background. Centered composition with soft shadow. Museum-grade collectible photography. Hot Wheels-inspired proportions with strong silhouette and personality. Mixed metals, scratches, visible bolts and cables. Vertical 9:16 aspect ratio.', 2);
INSERT INTO public.shikai_images (collection_id, file_url, prompt, sort_order) VALUES
    ('28', '/projects/shikai/Shikai Collection/Shikai Cosmic Rides/Gemini_Generated_Image_s2xvbks2xvbks2xv.png', 'A premium 3D collectible vehicle for the Shikai Cosmic Rides series. Ultra-detailed 3D render on clean white studio background. Centered composition with realistic shadow beneath. Museum-grade collectible product photography. Hot Wheels-inspired toy-like forms. Each vehicle feels hand-built, unique, and story-driven. Mixed metals with wear. Vertical 9:16 aspect ratio.', 3);
